//@@ START - bk_prof_bef_tax
// Book Profit Before Tax                                                                                             
// Column:BK_PROF_BEF_TAX
//========================================================
double SEG_COMP_UDF::seg_comp_bk_prof_bef_tax(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(62,"bk_prof_bef_tax",t);
}



//^^^

#line 1 "bk_prof_bef_tax.SEG_COMP.for"
if (t <= start_period || t > final_period)
	return NO_AVG;

if (corp_seg_flag)
	return inv_inc_bk_prof(t)
		   - hedge_cost(t);	

// force calls
bk_prof_by_source_bef_tax(t);
liab_cash_flow(t);

return prem_paid(t)
	   + div_applied(t)
	   + annuitzn_inc(t)
	   + deferred_gross_prem_incr(t)
	   - stat_unearn_prem_res_incr(t)
	   + inv_inc_bk_prof(t)
	   + inv_fee_ref(t)
	   - dth_benefits(t)
	   - ann_benefits_bom(t)
	   - ann_benefits_eom(t)
	   - endow_benefits(t)
	   - conversion_cost(t)
	   - maturity_benefits(t)
	   - surr_benefits(t)
	   - withdrl_benefits(t)
	   - claim_paid(t)
	   - prem_waiver_benefits(t)	
	   - div_paid(t)
	   - terminal_div(t)
	   - stat_loading_incr(t)
	   - stat_claim_res_incr(t)
	   - stat_prem_waiver_res_incr(t)
       - stat_res_incr(t)
	   + loc_asset_incr(t)
       - comm_bom(t)
	   - comm_eom(t)
	   + comm_chargeback(t)
	   - acq_exp(t)
	   - maint_exp_bom(t)
	   - maint_exp_eom(t)
	   - prem_tax(t)
       - stat_claim_exp_res_incr(t)
	   - stat_prem_waiver_exp_res_incr(t)
	   - loc_cost(t)
	   - reins_stat_cost(t)
	   - hedge_cost(t)	
	   - div_liab_incr(t)
       - transfer_to_sa_net(t)
	   - xol_prem_aig(t); //20230127 SJ: For XOL Deal, deduct XOL premium from profits.

}


