//@@ START - cash_int
// Cash Interest                                                                                             
// Column:CASH_INT
//========================================================
double SEG_COMP_UDF::seg_comp_cash_int(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(92,"cash_int",t);
}



//^^^

#line 1 "cash_int.SEG_COMP.for"
if (!alm_flag || t < start_period || t > final_period)
	return NO_AVG;

if (t == start_period)
	return cash(t)
		   * (pow(1.0 + cash_rate(t), 1.0 / 12.0) - 1.0);

if (res_ag38_8d_valn_flag)
	{
	double cash_incr = 0.0;
	double ag38_8d_cash_rate = 0.0;//suppose all AG38 8D new investments are in cash earning this rate
	
	cash_incr = cash(t - 1) - hedge_inv_amt_bom(t) - init_cash_ag38_8d;
	
	ag38_8d_cash_rate = min(company->get_comp_rate(asset_yld_comp_rate_id, t), 0.07);
	
	if ((cash(t - 1) - hedge_inv_amt_bom(t)) < model_point_amount_threshold)
		return 0.0;
		
	return init_cash_ag38_8d * (pow(1.0 + cash_rate(t), 1.0 / 12.0) - 1.0)
		   + cash_incr * (pow(1.0 + ag38_8d_cash_rate, 1.0 / 12.0) - 1.0);
	
	}

return (cash(t - 1) - hedge_inv_amt_bom(t) - hedge_rila_trading_cost_aig(t)) //20240529 MQ RILA trading cost
	   * (pow(1.0 + cash_rate(t), 1.0 / 12.0) - 1.0);

}


