//@@ START - distribn
// Distribution                                                                                             
// Column:DISTRIBN
//========================================================
double SEG_COMP_UDF::seg_comp_distribn(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(128,"distribn",t);
}



//^^^

#line 1 "distribn.SEG_COMP.for"
if (pba_valn_flag || t <= start_period || t > final_period || vm21_reinv_rate_seg_flag)
	return NO_AVG;

// In total company model, business segments distribute all earnings to corporate segment
if (nb_flag || (tcm_flag && business_seg_flag))
	return distrib_earnings(t);

if (company->distribn_pct_distrib_earnings == 0.0
	&& company->distribn_pct_free_surp == 0.0)
	return NO_AVG;

double distribn_distrib_earnings = 0.0;
double distribn_free_surp = 0.0;

if (company->distribn_pct_distrib_earnings > 0)
	distribn_distrib_earnings	
	=  company->distribn_pct_distrib_earnings
       * distrib_earnings(t);

if (company->distribn_pct_free_surp > 0)
	{
	if (company->prof_distribn_mode == MONTHLY
		|| (company->prof_distribn_mode == QUARTERLY
			 && xint(cal_mth(t)) % 3 == 0)
		|| (company->prof_distribn_mode == ANNUAL
		    && cal_mth(t) == 12))
		{
		distribn_free_surp
		= company->distribn_pct_free_surp
		  * free_surp(t - 1);
		}
	}

return distribn_distrib_earnings
       + distribn_free_surp;

}


