//@@ START - gaap_deferred_tax_liab
// GAAP Deferred Tax Liability                                                                                             
// Column:GAAP_DEFERRED_TAX_LIAB
//========================================================
double SEG_COMP_UDF::seg_comp_gaap_deferred_tax_liab(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(191,"gaap_deferred_tax_liab",t);
}



//^^^

#line 1 "gaap_deferred_tax_liab.SEG_COMP.for"
if (!gaap_flag || t < start_period || t > final_period)
	return NO_AVG;

if (nb_flag && t == start_period
	&& valn_period == 0)
	return NO_AVG;
	
double tax_rate = company->tax_rate;

return tax_rate
       * ((tax_res(t)
	        - reins_tax_res(t))
          - (tax_deferred_net_prem(t)
             - reins_tax_deferred_net_prem(t))
          + (tax_div_liab(t)
             - reins_tax_div_liab(t))
          - tax_capzd_prem_unamortzd(t)
          + company->taxable_inc_addn_unamortzd // Input variable is future amount at each date to be amortized into taxable income
          - (gaap_liab_net(t)
             - reins_gaap_liab_net(t))
          + gaap_surp_unrealzd_cap_gain(t));

}


//@@ END

