double SEG_COMP_UDF::seg_comp_gaap_inc_bef_tax(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(208,"gaap_inc_bef_tax",t);
}



//^^^

#line 1 "gaap_inc_bef_tax.SEG_COMP.for"
if (!gaap_flag || t <= start_period || t > final_period)
	return NO_AVG;

double gaap_inc_bef_tax = 0.0;

// force call actual gross profits and actual gross margin
double agp = sum_over_sfas97rd("agp", t, GROSS);
double agm = sum_over_sfas120("agm", t, GROSS);

//force calls for reporting
gaap_capzd_acq_exp(t);
gaap_capzd_comm_bom(t);
gaap_capzd_comm_eom(t);
gaap_capzd_prem_bonus(t);
gaap_capzd_reins_yrt_cost(t);
sum_over_sfas60("detail_rpt_driver", t, GROSS);
sum_over_sfas97lp("detail_rpt_driver", t, GROSS);
sum_over_sfas60("inv_inc", t, GROSS);
sum_over_sfas91("inv_inc", t, GROSS);
sum_over_sfas97lp("inv_inc", t, GROSS);
sum_over_sfas97rd("inv_inc", t, GROSS);
sum_over_sfas120("inv_inc", t, GROSS);
sum_over_sfas60("cap_gain", t, GROSS);
sum_over_sfas91("cap_gain", t, GROSS);
sum_over_sfas97lp("cap_gain", t, GROSS);
sum_over_sfas97rd("cap_gain", t, GROSS);
sum_over_sfas120("cap_gain", t, GROSS);

gaap_inc_bef_tax
= gaap_gross_prem(t)
  + gaap_div_applied(t)
  + gaap_loads_deducted(t)
  - gaap_loads_deferred(t)
  + gaap_chg_inc(t)
  + gaap_surr_inc(t)
  + gaap_unearn_rev_released(t)
  + gaap_cash_flow_int(t)
  + gaap_inv_inc_res(t)
  + gaap_cap_gain_res(t)
  + gaap_inv_inc_cap(t)
  + gaap_cap_gain_cap(t)
  - gaap_prem_bonus(t)
  - gaap_credited_int(t)
  - gaap_dth_claim_cost(t)
  - gaap_ann_claim_cost(t)
  - gaap_hlth_claim_cost(t)
  - gaap_surr_claim_cost(t)
  - gaap_maturity_claim_cost(t)
  - gaap_endow_claim_cost(t)
  - gaap_inc_ben_claim_cost(t)
  - gaap_accum_ben_claim_cost(t)
  - gaap_withdrl_ben_claim_cost(t)
  - gaap_div_paid(t)
  - gaap_terminal_div(t)
  - gaap_ben_res_incr(t)
  - gaap_maint_exp_res_incr(t)
  - gaap_deferred_prof_liab_incr(t)
  - gaap_claim_res_incr(t)
  - gaap_prem_waiver_res_incr(t)
  - gaap_sfas133_liab_incr(t)
  - gaap_sop031_addl_liab_incr(t)
  - gaap_div_liab_incr(t)
  - gaap_acq_exp(t)
  - gaap_comm_excess_bom(t)
  - gaap_comm_excess_eom(t)
  - gaap_comm_trail_bom(t)
  - gaap_comm_trail_eom(t)
  + gaap_deferred_maint_exp(t)
  - gaap_maint_exp_bom(t)
  - gaap_maint_exp_eom(t)
  - gaap_prem_tax(t)
  - gaap_loc_cost(t)
  + gaap_dac_incr(t)
  - gaap_conversion_cost(t)
  - gaap_reins_yrt_cost(t) // Cost for the YRT treaties
  - reins_gaap_cost(t) 
  - gaap_hedge_cost(t);

return gaap_inc_bef_tax;

}


