//@@ START - gaap_inv_inc_res
// GAAP Investment Income on Reserves                                                                                             
// Column:GAAP_INV_INC_RES
//========================================================
double SEG_COMP_UDF::seg_comp_gaap_inv_inc_res(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(222,"gaap_inv_inc_res",t);
}



//^^^

#line 1 "gaap_inv_inc_res.SEG_COMP.for"
if (!gaap_flag || corp_seg_flag || t <= start_period || t > final_period)
	return NO_AVG;
	
if ((fabs(stat_res(t - 1) + div_liab(t - 1)
    	- deferred_net_prem(t - 1) - loc_asset(t - 1) - pol_loan(t - 1)))
     > rate_ratio_threshold)
	return inv_inc_res(t)
	        * (gaap_liab_net(t - 1)
               - pol_loan(t - 1))
	        / (stat_res(t - 1) 
    	       + div_liab(t - 1)
    	       - deferred_net_prem(t - 1)
               - loc_asset(t - 1) 
    	       - pol_loan(t - 1)) 
	       + pol_loan_inc(t);

if (!alm_flag
    && fabs(stat_res(t - 1) + div_liab(t - 1)
    	    - deferred_net_prem(t - 1) - pol_loan(t - 1)) 
       < rate_ratio_threshold)
	return (pow((1.0 + asset_yld(t)), (1.0 / 12.0)) - 1)
	         * (gaap_liab_net(t - 1) - pol_loan(t - 1))
	        + pol_loan_inc(t);

if (alm_flag
    && fabs(stat_res(t - 1) + div_liab(t - 1)
    	    - deferred_net_prem(t - 1) - pol_loan(t - 1)) 
       < rate_ratio_threshold)
	return inv_inc_res(t)
	       + (pow((1.0 + asset_yld(t)),(1.0 / 12.0)) - 1)
	         * (gaap_liab_net(t - 1) - pol_loan(t - 1))
	       + pol_loan_inc(t);

return NO_AVG;

}


