//@@ START - imr
// IMR                                                                                             
// Column:IMR
//========================================================
double SEG_COMP_UDF::seg_comp_imr(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(280,"imr",t);
}



//^^^

#line 1 "imr.SEG_COMP.for"
if (!imr_flag || t < start_period || t >= final_period) //t > final_period)  //changed by HYH 08/27/2021
	return NO_AVG;

if (nb_flag && t == start_period
	&& valn_period == 0)
	return NO_AVG;

if (t == start_period)
	{
	if (existing_asset_pct_to_use_defn == APPLY_PERCENTAGE_TO_ASSETS_ONLY)
		return init_imr;

	return init_imr * existing_asset_pct_to_use;
	}

// restrict imr to not exceed estimated invested assets
double imr_bef_adj
= imr(t - 1)
  + imr_cap_gain_net(t)
  - imr_amortzn_for_mth(t);

//20210927 STW: add different options for IMR
if(imr_options_aig == NO_IMR)
{
	return 0.0;		  // enable this line to set IMR to 0
}
else if(imr_options_aig == NO_IMR_WRITE_OFF)
{
	return imr_bef_adj; // enable this line to remove IMR write-off
}
else if(imr_options_aig == NO_NEGATIVE_IMR)
{
	return max(imr_bef_adj, 0);  //enable this line to set IMR to non-negative
}
else if(imr_options_aig == IMR_AND_ADJ || imr_options_aig == IMR_AND_NO_ADJ)
{
	//use the following if allowing negative IMR
	double inv_asset_with_pol_loan_est
	= inv_asset(t - 1)
	  + liab_cash_flow(t)
	  + asset_cash_flow_bef_inv(t)
	  - tax(t)
	  + pol_loan(t);

	// don't let imr drop below negative invested assets
	if (inv_asset_with_pol_loan_est < -model_point_amount_threshold)
		return max(imr_bef_adj, inv_asset_with_pol_loan_est);  //changed by HYH 09/03/2021

	// don't let imr exceed positive invested assets
	if (inv_asset_with_pol_loan_est > model_point_amount_threshold)  //added by HYH 09/03/2021
		return min(imr_bef_adj, inv_asset_with_pol_loan_est);

	// -model_point_amount_threshold <= invested assets <= model_point_amount_threshold
	return 0.0;
}
else
{
	throw FatalError("imr_options_aig is not set to a valid option.");
}

}


//@@ END

//@@ START - imr_amortzn_adj
// IMR Amortization adjustment for Month                                                                                             
// Column:IMR_AMORTZN_ADJ
//========================================================
double SEG_COMP_UDF::seg_comp_imr_amortzn_adj(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(281,"imr_amortzn_adj",t);
}



//^^^

#line 1 "imr_amortzn_adj.SEG_COMP.for"
//Added by HYH 09/03/2021, to adjust imr_amortzn_amt_tbl and imr_fy_amortzn_for_mth
if (!imr_flag || t < start_period || t >= final_period) 
	return 1.0; //NO_AVG;

if (nb_flag && t == start_period
	&& valn_period == 0)
	return 1.0; //NO_AVG;

if (t == start_period)
	{
	if (existing_asset_pct_to_use_defn == APPLY_PERCENTAGE_TO_ASSETS_ONLY)
		return 1.0;

	return existing_asset_pct_to_use;
	}

// restrict imr to not exceed estimated invested assets
double imr_bef_adj
= imr(t - 1)
  + imr_cap_gain_net(t)
  - imr_amortzn_for_mth(t);

//20210927 STW: add different options for IMR adjustment
if(imr_options_aig == NO_IMR)
{
	return 0.0;		  // enable this line to set IMR to 0
}
else if(imr_options_aig == NO_IMR_WRITE_OFF)
{
	return 1.0;
}
else if(imr_options_aig == NO_NEGATIVE_IMR)
{
	//enable this line to set IMR to non-negative
	if (imr_bef_adj <= 0) return 0.0;
	return 1.0;
}
else if(imr_options_aig == IMR_AND_ADJ)
{
	//use the following if allowing negative IMR
	double inv_asset_with_pol_loan_est
	= inv_asset(t - 1)
	  + liab_cash_flow(t)
	  + asset_cash_flow_bef_inv(t)
	  - tax(t)
	  + pol_loan(t);

	// when imr drop below negative invested assets
	if (inv_asset_with_pol_loan_est < -model_point_amount_threshold && inv_asset_with_pol_loan_est > imr_bef_adj)
		return inv_asset_with_pol_loan_est / imr_bef_adj; // * imr_amortzn_adj(t-1);

	// when imr exceed positive invested assets
	if (inv_asset_with_pol_loan_est > model_point_amount_threshold && inv_asset_with_pol_loan_est < imr_bef_adj)
		return inv_asset_with_pol_loan_est / imr_bef_adj; // * imr_amortzn_adj(t-1);

	// when invested assets is almost zero
	if (inv_asset_with_pol_loan_est <= model_point_amount_threshold && inv_asset_with_pol_loan_est >= -model_point_amount_threshold)
		return 0.0; // * imr_amortzn_adj(t-1);

	return 1.0; // imr_amortzn_adj(t-1);
}
else if(imr_options_aig == IMR_AND_NO_ADJ)
{
	return 1.0;
}
else
{
	throw FatalError("imr_options_aig is not set to a valid option.");
}

}


//@@ END

