//@@ START - infl_cumul
// Inflation Cumulative                                                                                             
// Column:INFL_CUMUL
//========================================================
double SEG_COMP_UDF::seg_comp_infl_cumul(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(299,"infl_cumul",t);
}



//^^^

#line 1 "infl_cumul.SEG_COMP.for"
if (t < start_period || t > final_period)
	return 1.0;

if (nb_flag && t == start_period
	&& valn_period == 0)
	return 1.0;

if (t <= infl_start_period)
	return 1.0;

if (t == start_period && infl_start_period < start_period)
	{
	double init_infl_cumul = 1.0;

	for (int i = infl_start_period + 1; i <= start_period; i++)
		{
		double infl_rate
		= rates->get_infl_rate(i, EFFECTIVE_ANNUAL);

		init_infl_cumul *= pow((1.0 + infl_rate), (1.0 / 12.0));
		}

	return init_infl_cumul;
	}

double infl_rate
= rates->get_infl_rate(t, EFFECTIVE_ANNUAL);

return infl_cumul(t - 1) 
       * pow((1.0 + infl_rate), (1.0 /12.0));

}


