//@@ START - rbc_c1
// RBC C1                                                                                             
// Column:RBC_C1
//========================================================
double SEG_COMP_UDF::seg_comp_rbc_c1(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(363,"rbc_c1",t);
}



//^^^

#line 1 "rbc_c1.SEG_COMP.for"
if (!tgt_cap_flag || t < start_period || t > final_period)
	return NO_AVG;

if (nb_flag && t == start_period
	&& valn_period == 0)
	return NO_AVG;

if (t == start_period && valn_period != 0)
	return init_rbc_c1;

if (alm_flag)
	{
	if (sale_imr_avr_flag(t))
		return (rbc_c1_non_eqt(t)
				* company->rbc_c1_port_size_mult
				* company->rbc_c1_concentration_mult_other)
			   + (rbc_cash(t)
				  * company->rbc_c1_cash_pct)
			   + (reins_stat_res(t)
				  * company->rbc_c1_reins_res_pct);

	return (rbc_c1_non_eqt_bef_sale(t)
			* company->rbc_c1_port_size_mult
			* company->rbc_c1_concentration_mult_other)
		   + (rbc_cash_bef_sale(t)
			  * company->rbc_c1_cash_pct)
		   + (reins_stat_res(t)
			  * company->rbc_c1_reins_res_pct);
	}

return max(0.0, 
		   stat_res(t)
		   - reins_stat_res(t)
		   + rbc_c1_unearn_prem_res_def(t)
		   + stat_res_sa(t))
        * company->rbc_c1_liab_only_stat_res_pct;

}


