//@@ START - rbc_c2
// RBC C2                                                                                             
// Column:RBC_C2
//========================================================
double SEG_COMP_UDF::seg_comp_rbc_c2(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(370,"rbc_c2",t);
}



//^^^

#line 1 "rbc_c2.SEG_COMP.for"
if (!tgt_cap_flag || corp_seg_flag || t < start_period || t > final_period)
	return NO_AVG;

if (nb_flag && t == start_period
	&& valn_period == 0)
	return NO_AVG;

double rbc_c2_claim_used = 0.0;
if (rbc_c2_loss_ratio(t) < rate_ratio_threshold)
	rbc_c2_claim_used = rbc_c2_claim(t);
else
	rbc_c2_claim_used = rbc_c2_loss_ratio(t) * rbc_c2_prem(t);

double rbc_c2_claim_res = stat_claim_res(t) 
						  + stat_prem_waiver_res(t) 
						  - reins_stat_claim_res(t) 
						  - reins_stat_prem_waiver_res(t);

return company->rbc_c2_mort_pct* rbc_c2_nar(t)
	   + company->rbc_c2_morbid_prem_pct * rbc_c2_prem(t)
	   + company->rbc_c2_morbid_claim_pct * rbc_c2_claim_used
	   + company->rbc_c2_morbid_res_pct * rbc_c2_claim_res;

}


