//@@ START - rbc_c2_loss_ratio
// RBC C2 Loss Ratio                                                                                             
// Column:RBC_C2_LOSS_RATIO
//========================================================
double SEG_COMP_UDF::seg_comp_rbc_c2_loss_ratio(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(373,"rbc_c2_loss_ratio",t);
}



//^^^

#line 1 "rbc_c2_loss_ratio.SEG_COMP.for"
if (!tgt_cap_flag || corp_seg_flag || t < start_period || t > final_period)
	return NO_AVG;

if (nb_flag && t == start_period
	&& valn_period == 0)
	return NO_AVG;

if (rbc_c2_prem(t) < rate_ratio_threshold
	|| rbc_c2_prem_prev_yr(t) < rate_ratio_threshold
	|| rbc_c2_claim(t) < rate_ratio_threshold
	|| rbc_c2_claim_prev_yr(t) < rate_ratio_threshold)
	return NO_AVG;

double loss_ratio_curr_yr = rbc_c2_claim(t) / rbc_c2_prem(t);
double loss_ratio_prev_yr = rbc_c2_claim_prev_yr(t) / rbc_c2_prem_prev_yr(t);

return (loss_ratio_curr_yr + loss_ratio_prev_yr) / 2.0;

}


