//@@ START - rbc_c3_hedge_offset
// RBC C3 Hedge Offset                                                                                             
// Column:RBC_C3_HEDGE_OFFSET
//========================================================
double SEG_COMP_UDF::seg_comp_rbc_c3_hedge_offset(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(378,"rbc_c3_hedge_offset",t);
}



//^^^

#line 1 "rbc_c3_hedge_offset.SEG_COMP.for"
if (!tgt_cap_flag || corp_seg_flag || t < start_period || t > final_period)
	return NO_AVG;

if (nb_flag && t == start_period
	&& valn_period == 0)
	return NO_AVG;

#if defined(__LIFE_PBA_PBA_H_)
// currently there is no hedging in life PBA calculations
return NO_AVG;
#endif

#if defined(__VA_PBA_PBA_H_)
if (sm_va_pba[0]->res_cap_calc_defn == NOT_APPLICABLE
	|| sm_va_pba[0]->res_cap_calc_defn == RESERVES
	|| sm_va_pba[0]->hedging_defn == UNHEDGED)
	return NO_AVG;

if (t == start_period && valn_period != 0)
	return init_rbc_c3_hedge_offset;
	
if (t == start_period && valn_period == 0
	|| (t == start_period + 1 && valn_period > 0)
	|| (nb_flag && t == start_period + 1 && valn_period == 0))
	{
	rbc_std_scen_valn_flag = true;
	StrEnum::EnumValue pba_calc_defn = sm_va_pba[0]->res_cap_calc_defn;
	StrEnum::EnumValue pba_reins_defn = sm_va_pba[0]->reins_defn;
	StrEnum::EnumValue pba_hedging_defn = sm_va_pba[0]->hedging_defn;
	
	sm_va_pba[0]->pba_code = STD_SCEN_CAP;
	sm_va_pba[0]->res_cap_calc_defn = CAPITAL;
	sm_va_pba[0]->reins_defn = NET;
	sm_va_pba[0]->hedging_defn = HEDGED;
	sm_va_pba[0]->hedging_cash_flow_defn = EXISTING;
	
	sm_va_pba[0]->ms_rereadGrid();
	
	// if not hedged, return 0.0
	if (!sm_va_pba[0]->hedging_flag)
		{
		// restore pba definitions
		sm_va_pba[0]->res_cap_calc_defn = pba_calc_defn;
		sm_va_pba[0]->reins_defn = pba_reins_defn;
		sm_va_pba[0]->hedging_defn = pba_hedging_defn;
	
		return 0.0;
		}
	
	double hedge_offset = sm_va_pba[0]->hedge_value_existing_hedges(t);
	
	sm_va_pba[0]->resetValues();
	
	// restore pba definitions
	sm_va_pba[0]->res_cap_calc_defn = pba_calc_defn;
	sm_va_pba[0]->reins_defn = pba_reins_defn;
	sm_va_pba[0]->hedging_defn = pba_hedging_defn;
	rbc_std_scen_valn_flag = false;

	return hedge_offset * pba_rollforward_factor(t);
	}
else
	{
	return rbc_c3_hedge_offset(t - 1) 
		   * pba_rollforward_factor(t);
	}
#endif

#if defined(__ANN_PBA_PBA_H_)
// currently there is no deterministic calculation in annuity PBA calculations
return NO_AVG;
#endif

return NO_AVG;

}


