//========================================================
double SEG_COMP_UDF::seg_comp_rbc_c3_unhedged(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(384,"rbc_c3_unhedged",t);
}



//^^^

#line 1 "rbc_c3_unhedged.SEG_COMP.for"
if (!tgt_cap_flag || corp_seg_flag || t < start_period || t > final_period)
	return NO_AVG;

if (nb_flag && t == start_period
	&& valn_period == 0)
	return NO_AVG;

#if defined(__LIFE_PBA_PBA_H_)
if (sm_life_pba[0]->res_cap_calc_defn == NOT_APPLICABLE
    || sm_life_pba[0]->res_cap_calc_defn == RESERVES)
	return rbc_c3_mp(t);

return max(rbc_c3_stoch_amt_unhedged(t) - (stat_res_net_unhedged(t) + stat_res_sa(t)), 0.0);
#endif

#if defined(__VA_PBA_PBA_H_)
if (sm_va_pba[0]->res_cap_calc_defn == NOT_APPLICABLE
    || sm_va_pba[0]->res_cap_calc_defn == RESERVES)
	return rbc_c3_mp(t);

return max(max(rbc_c3_stoch_amt_unhedged(t), rbc_c3_std_scen_amt_unhedged(t))
           - (stat_res_net_unhedged(t) + stat_res_sa(t)), 0.0);
#endif

#if defined(__ANN_PBA_PBA_H_)
if (!vm21_reinv_rate_seg_flag) //VM21-Workaround
{
	if (sm_ann_pba[0]->res_cap_calc_defn == NOT_APPLICABLE
    || sm_ann_pba[0]->res_cap_calc_defn == RESERVES)
	return rbc_c3_mp(t);
}


return max(rbc_c3_stoch_amt_unhedged(t) - stat_res_net_unhedged(t), 0.0);
#endif

return rbc_c3_mp(t);

}


