//@@ START - rbc_cash
// RBC Cash Amount                                                                                             
// Column:RBC_CASH
//========================================================
double SEG_COMP_UDF::seg_comp_rbc_cash(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(386,"rbc_cash",t);
}



//^^^

#line 1 "rbc_cash.SEG_COMP.for"
if (!tgt_cap_flag || !alm_flag  || t < start_period || t > final_period)
	return NO_AVG;

if (nb_flag && t == start_period
	&& valn_period == 0)
	return NO_AVG;

if (t == start_period)
	{
	if (valn_period > 0)
		return init_rbc_cash;

	return cash(t)
	       + borrowing(t);
	}
	
double preliminary_rbc_cash 
	   = cash(t - 1)
	     + borrowing(t - 1)
		 + interim_cash(t - 1)
		 + liab_cash_flow_bom(t)
		 + liab_cash_flow_eom(t)
		 + int_pmt(t)
		 - inv_exp(t)
		 + opt_inc(t)
		 + sched_prin_pmt(t)
		 + opt_pmt(t)
		 + cash_int(t)
		 + borrowing_int(t)
		 + interim_cash_int(t)
		 + cash_flow_int(t)
		 - tax_bk_prof(t)
		 - tax_tgt_cap(t)
		 - tax_free_surp(t);

if (sale_imr_avr_flag(t))
	return preliminary_rbc_cash
	  	   + contribn_from_business_seg_bef_sale(t)
		   - distribn_bef_sale(t)
		   - cash_flow_invested(t)
		   + mkt_val_sale(t);

return preliminary_rbc_cash
	   + mkt_val_sale(t);

}


//@@ END

//@@ START - rbc_cash_bef_sale
// RBC Cash Before Sales                                                                                             
// Column:RBC_CASH_BEF_SALE
//========================================================
double SEG_COMP_UDF::seg_comp_rbc_cash_bef_sale(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(387,"rbc_cash_bef_sale",t);
}



//^^^

#line 1 "rbc_cash_bef_sale.SEG_COMP.for"
if (!tgt_cap_flag || !alm_flag  || t < start_period || t > final_period)
	return NO_AVG;

if (nb_flag && t == start_period
	&& valn_period == 0)
	return NO_AVG;

if (t == start_period)
	return cash(t)
	       + borrowing(t);
	
return cash(t - 1)
       + borrowing(t - 1)
	   + interim_cash(t - 1)
	   + liab_cash_flow_bom(t)
	   + liab_cash_flow_eom(t)
	   + int_pmt(t)
	   - inv_exp(t)
	   + opt_inc(t)
	   + sched_prin_pmt(t)
	   + opt_pmt(t)
	   + cash_int(t)
	   + borrowing_int(t)
	   + interim_cash_int(t)
	   + cash_flow_int(t)
	   - tax_bk_prof_bef_sale(t)
	   - tax_tgt_cap_bef_sale(t)
	   - tax_free_surp_bef_sale(t);

}


