//@@ START - realzd_cap_gain_free_surp
// Realized Capital Gains on Free Surplus                                                                                             
// Column:REALZD_CAP_GAIN_FREE_SURP
//========================================================
double SEG_COMP_UDF::seg_comp_realzd_cap_gain_free_surp(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(390,"realzd_cap_gain_free_surp",t);
}



//^^^

#line 1 "realzd_cap_gain_free_surp.SEG_COMP.for"
if (!alm_flag || (tcm_flag && business_seg_flag) || t <= start_period || t > final_period)
	return NO_AVG;

if (fabs(inv_asset(t - 1)) < rate_ratio_threshold)
	return NO_AVG;
	
return free_surp(t - 1)
       * realzd_cap_gain(t)
       / inv_asset(t - 1);

}


