//@@ START - reins_gaap_cap_gain_res
// Reinsurance GAAP Capital Gain on Reserves                                                                                             
// Column:REINS_GAAP_CAP_GAIN_RES
//========================================================
double SEG_COMP_UDF::seg_comp_reins_gaap_cap_gain_res(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(439,"reins_gaap_cap_gain_res",t);
}



//^^^

#line 1 "reins_gaap_cap_gain_res.SEG_COMP.for"
if (!gaap_flag || !alm_flag || !reins_flag || t <= start_period || t > final_period)
	return NO_AVG;

if (fabs(gaap_liab_net(t - 1) - pol_loan(t - 1)) < rate_ratio_threshold)
	return NO_AVG;

return (gaap_cap_gain_res(t)
	    - gaap_inc_unrealzd_cap_gain_incr(t) 
	    - pol_loan_inc(t))
	    * (reins_gaap_liab_net(t - 1)) 
	        / (gaap_liab_net(t - 1) - pol_loan(t - 1)) 
	    + reins_gaap_unrealzd_cap_gain_incr(t);

}


