		sm_life_pba[i]->resetValues();
	
	// restore pba definitions
	sm_life_pba[0]->res_cap_calc_defn = pba_calc_defn;
	sm_life_pba[0]->reins_defn = pba_reins_defn;

	return ag38_8d_res;
