//@@ START - stat_res_unhedged
// Statutory Reserve Unhedged                                                                                             
// Column:STAT_RES_UNHEDGED
//========================================================
double SEG_COMP_UDF::seg_comp_stat_res_unhedged(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(612,"stat_res_unhedged",t);
}



//^^^

#line 1 "stat_res_unhedged.SEG_COMP.for"
if (corp_seg_flag || t < start_period || t > final_period)
	return NO_AVG;

if (nb_flag && t == start_period
	&& valn_period == 0)
	return NO_AVG;

#if defined(__LIFE_PBA_PBA_H_)
if (sm_life_pba[0]->res_cap_calc_defn == NOT_APPLICABLE
	|| sm_life_pba[0]->res_cap_calc_defn == CAPITAL)
	return stat_res_mp(t);

// Force calls for reporting
stat_res_stoch_res_unhedged(t);
stat_res_det_res_unhedged(t);
stat_res_npr_unhedged(t);
deferred_net_prem_npr(t);

return stat_res_mp_unhedged(t) + stat_res_ag38_8d(t);
#endif

#if defined(__VA_PBA_PBA_H_)
if (sm_va_pba[0]->res_cap_calc_defn == NOT_APPLICABLE
	|| sm_va_pba[0]->res_cap_calc_defn == CAPITAL)
	return stat_res_mp(t);

return max(stat_res_stoch_res_unhedged(t), stat_res_npr_unhedged(t))
       - stat_res_sa(t);
#endif

#if defined(__ANN_PBA_PBA_H_)
if (sm_ann_pba[0]->res_cap_calc_defn == NOT_APPLICABLE
	|| sm_ann_pba[0]->res_cap_calc_defn == CAPITAL)
	return stat_res_mp(t);

return max(stat_res_stoch_res_unhedged(t), stat_res_npr(t));
#endif

return NO_AVG;

}


