	   + bk_prof_aft_tax(t)
	   - tgt_cap_incr(t)
	   + inv_inc_tgt_cap(t)
	   + cap_gain_tgt_cap(t)
	   - imr_impact_tgt_cap(t)
	   - tax_tgt_cap(t)
	   + contribn_from_business_seg(t);
	
