//========================================================
double SEG_COMP_UDF::seg_comp_vm21_pv_claims_deterministic_crbg(int t) {
//^^^



//^^^

#line 1 "vm21_pv_claims_deterministic_crbg.SEG_COMP.for"
//20250410 MQ new column
if (corp_seg_flag || t < start_period || t > final_period)
	return NO_AVG;

if (t == start_period && valn_period == 0)
	return NO_AVG;

if (t == start_period && valn_period != 0)
	return init_pv_claims_determinstic;

if (t == 1)
{
	double pv_claims_init = sum_over_liabilities("vm21_pv_claims_deterministic_crbg", t); //This is BOM
	
	return pv_claims_init * pba_rollforward_factor(t); //Roll forward to EOM
}

else 
{
	return vm21_pv_claims_deterministic_crbg(t - 1) * pba_rollforward_factor(t);
}

}


