#define MAXIMUM_RESERVE        2
#define BASIC_CONTRIBUTION     3
#define RESERVE_OBJECTIVE      4
int detail_selection = REALIZED_CAPITAL_GAINS;

// these depend on the detail_selection (see code below)
xstring detail_header = "";
int component_bonds = 0;
int component_mortgages = 0;
int component_stock = 0;
int component_other = 0;
double detail_value = 0;

bool detail_wanted = false;

if (avr_detail_log_flag(r))
	{
	detail_wanted = true;
	
	log_screen << "avr-> r=" << r << " before sales" << MSG_USER;
	if (detail_selection == REALIZED_CAPITAL_GAINS)
		{
		detail_header   = " avr_real_cap_gain";
		component_bonds     = REALZD_CAP_GAIN_bonds;
		component_mortgages = REALZD_CAP_GAIN_mortgages;
		component_stock     = REALZD_CAP_GAIN_stock;
		component_other     = REALZD_CAP_GAIN_other;
		}
	else if (detail_selection == MAXIMUM_RESERVE)
		{
		detail_header       = "   avr_max_reserve";
		component_bonds     = MAX_RES_bonds;
		component_mortgages = MAX_RES_mortgages;
		component_stock     = MAX_RES_stock;
		component_other     = MAX_RES_other;
		}
	else if (detail_selection == BASIC_CONTRIBUTION)
		{
		detail_header       = " avr_basic_contrib";
		component_bonds     = BASIC_CONTRIB_bonds;
		component_mortgages = BASIC_CONTRIB_mortgages;
		component_stock     = BASIC_CONTRIB_stock;
		component_other     = BASIC_CONTRIB_other;
		}
	else if (detail_selection == RESERVE_OBJECTIVE)
		{
		detail_header       = "   avr_reserve_obj";
		component_bonds     = RES_OBJ_bonds;
		component_mortgages = RES_OBJ_mortgages;
		component_stock     = RES_OBJ_stock;
		component_other     = RES_OBJ_other;
		}

	log_screen << "avr->  asset_id type " << detail_header
			<< "        total_bonds    total_mortgages        total_stock        total_other subcomponent" << MSG_USER;
	log_screen << "avr-> --------- ---- ------------------"
			<< " ------------------ ------------------ ------------------ ------------------ ------------------" << MSG_USER;
	}
#endif

int mp;
int avr_index;
mpmap::iterator mp_map_iter;

