//@@ START - reins_pct_ag38_8d
// Reinsurance Percent Ag38 8d                                                                                             
// Calculated Variable:REINS_PCT_AG38_8D
//========================================================
double SEG_COMP_UDF::seg_comp_reins_pct_ag38_8d() {
//^^^


#line 1 "reins_pct_ag38_8d.SEG_COMP.for"
int mp = 0;
double num = 0.0;
double denom = 0.0;
mpmap::iterator mp_map_iter;

#if defined(__UL_LIAB_H_)
for (mp_map_iter = ul_mp_map.begin();
     mp_map_iter != ul_mp_map.end();
     mp_map_iter++)
	{
	mp = mp_map_iter->first;

	if (liab->sm_ul[mp]->coins_flag && liab->sm_ul[mp]->stat_res_ag38_8d_defn == YES)
	       num += liab->sm_ul[mp]->reins_pct
		          * liab->sm_ul[mp]->dth_ben_inf(0);
			
	if (liab->sm_ul[mp]->stat_res_ag38_8d_defn == YES)
		denom += liab->sm_ul[mp]->dth_ben_inf(0);
	}
	
if (denom > 0.0)
	return num / denom;
#endif

return 0;

}


