    double N_p3_d1 = N_p1_d1 * (pow(d1 , 2) - 1);


    double P_ss = N_p1_d1 * exp(-q * T) / (S * sigma * pow(T, 0.5));

    double P_sigma = S * exp(-q * T) * N_p1_d1 * pow(T, 0.5);

