#line 1 "setup_asset_sub_ports.SEG_COMP.for"                                                                                   
void SEG_COMP::setup_asset_sub_ports(void)
{
#if defined(__A_SUBPORT_ASSET_H_)
log_screen << "... Initializing Asset Sub Portfolios for " << seg_id << MSG_USER;

int a_sub_port_size = company->sm_asset->sm_asset_sub_port[seg_num].size();
int a_sub_port_el_size = company->sm_asset->sm_asset_sub_port[seg_num][0].size();

if (SALFile && a_sub_port_size)
	SALFile << endl 
			<< "Asset Sub Portfolio Definitions" << endl 
			<< "SubPortID,AssetType,PortDefn,AssetCategory,AssetProjType,MinDurVal,MaxDurVal,MinAssetSize,"
			<< "DurMatchDefn,SalesPriority,RebalTolerance,MaxTurnover,MinTurnover,InvExpPct,PrxyBndCat,PrxyBndSalesClass" << endl;

for (int sub_port = 0; sub_port < a_sub_port_size; sub_port++)
	{
	for (int sub_port_el = 0; sub_port_el < a_sub_port_el_size; sub_port_el++)
		{
		// Set lookup key
		company->sm_asset->asset_sub_port_id = company->sm_asset->asset_sub_ports[sub_port];

		company->sm_asset->sm_asset_sub_port[seg_num][sub_port][sub_port_el]->seg = this;
	
		company->sm_asset->sm_asset_sub_port[seg_num][sub_port][sub_port_el]->seg_id = seg_id;
	
		company->sm_asset->sm_asset_sub_port[seg_num][sub_port][sub_port_el]->sub_port_id 
		= company->sm_asset->asset_sub_ports[sub_port];

		company->sm_asset->sm_asset_sub_port[seg_num][sub_port][sub_port_el]->asset_type 
		= company->sm_asset->asset_sub_port_asset_type;
	
		company->sm_asset->sm_asset_sub_port[seg_num][sub_port][sub_port_el]->port_defn 
		= company->sm_asset->asset_sub_port_port_defn;		
	
		company->sm_asset->sm_asset_sub_port[seg_num][sub_port][sub_port_el]->dur_match_defn 
		= company->sm_asset->asset_sub_port_dur_match_defn;
	
		company->sm_asset->sm_asset_sub_port[seg_num][sub_port][sub_port_el]->min_size_existing 
		= company->sm_asset->asset_sub_port_min_size;
	
		company->sm_asset->sm_asset_sub_port[seg_num][sub_port][sub_port_el]->min_size_purchase 
		= max(0.0, company->sm_asset->asset_sub_port_min_size);
	
		company->sm_asset->sm_asset_sub_port[seg_num][sub_port][sub_port_el]->sale_priority 
		= max(0, company->sm_asset->asset_sub_port_sale_priority);

		company->sm_asset->sm_asset_sub_port[seg_num][sub_port][sub_port_el]->rebal_tolerance_pct
		= max(0.0, min(1.0, company->sm_asset->asset_sub_port_rebal_tolerance_pct));

		// Make sure that 0.0 <= minimum turnover rate <= maximum turnover rate.
		company->sm_asset->sm_asset_sub_port[seg_num][sub_port][sub_port_el]->rebal_annual_turnover_pct_max
		= max(0.0, 
			  min(12.0, 
				  company->sm_asset->asset_sub_port_rebal_pct_max * 12.0));
		
		company->sm_asset->sm_asset_sub_port[seg_num][sub_port][sub_port_el]->rebal_annual_turnover_pct_min
		= max(0.0, 
			  min(company->sm_asset->sm_asset_sub_port[seg_num][sub_port][sub_port_el]->rebal_annual_turnover_pct_max, 
				  company->sm_asset->asset_sub_port_rebal_pct_min * 12.0));

		company->sm_asset->sm_asset_sub_port[seg_num][sub_port][sub_port_el]->inv_exp_pct 
		= company->sm_asset->asset_sub_port_inv_exp_pct;

		company->sm_asset->sm_asset_sub_port[seg_num][sub_port][sub_port_el]->initialize(0);

		if (sub_port_el == 0) // only capture the total element into the detail
			{
			if (SALFile)
				SALFile << company->sm_asset->asset_sub_ports[sub_port] << ","
						<< company->sm_asset->asset_sub_port_asset_type << ","
						<< company->sm_asset->asset_sub_port_port_defn << ","
						<< company->sm_asset->asset_sub_port_categories << ","
						<< company->sm_asset->asset_sub_port_existing_or_purch_defn << ","
						<< company->sm_asset->asset_sub_port_dur_min << ","
						<< company->sm_asset->asset_sub_port_dur_max << ","
						<< company->sm_asset->asset_sub_port_min_size << ","
						<< company->sm_asset->asset_sub_port_dur_match_defn << ","
						<< company->sm_asset->asset_sub_port_sale_priority << ","
						<< company->sm_asset->asset_sub_port_rebal_tolerance_pct << ","
						<< company->sm_asset->asset_sub_port_rebal_pct_max << ","
						<< company->sm_asset->asset_sub_port_rebal_pct_min << ","
						<< company->sm_asset->asset_sub_port_inv_exp_pct << ","
						<< company->sm_asset->asset_sub_port_proxy_bond_category << ","
						<< company->sm_asset->asset_sub_port_proxy_bond_sale_class << endl;
			}
		}
	}
#endif

return;
}



#line 1 "setup_hedge_groups.SEG_COMP.for"                                                                                   
void SEG_COMP::setup_hedge_groups(void)
{
#if defined(__HDG_GRP_COMP_H_)
if (is_first_proj_task_loop || num_of_proj_task_loops == 0
	|| restore_variables_ind == 1)
	{
	int total_mp_hedged = 0;
	hedge_grp_loop.clear();
	hedge_grp_loop_counter = 0; // hedge grp loop counter is a class variable
							
	if (sm_hedge_grp.size() && !hedge_valn_flag)
		log_screen << "... Initializing Hedge Groups for " << seg_id << MSG_USER;

	// Step 1: Initialize hedge grp map array	
	for (int hedge_group = 0; hedge_group < sm_hedge_grp.size(); hedge_group++)
		{
		int hedge_group_bucket_size = 0;
		if (hedge_valn_final_flag)
			hedge_group_bucket_size = company->hedge_valn_shock_list.size();
		else
			hedge_group_bucket_size = 1; // There is always one bucket for each hedge group

		// resize second dimension of hedge_grp initially to 1
		sm_hedge_grp[hedge_group].resize(hedge_group_bucket_size);
		sm_hedge_grp[hedge_group][0]->hedge_grp_count_id = hedge_group;
		
		for (int hedge_group_bucket = 0; hedge_group_bucket < hedge_group_bucket_size; hedge_group_bucket++)
			{
			sm_hedge_grp[hedge_group][hedge_group_bucket]->seg = this;
			sm_hedge_grp[hedge_group][hedge_group_bucket]->seg_id = seg_id;
			sm_hedge_grp[hedge_group][hedge_group_bucket]->hedge_grp_id = hedge_grps[hedge_group];

			#if defined (__VA_LIAB_H_)
			sm_hedge_grp[hedge_group][hedge_group_bucket]->hedge_grp_count_id = hedge_group;
			sm_hedge_grp[hedge_group][hedge_group_bucket]->hedge_grp_bucket_id = hedge_group_bucket;
			#endif

			sm_hedge_grp[hedge_group][hedge_group_bucket]->initialize(0);
			sm_hedge_grp[hedge_group][hedge_group_bucket]->ms_rereadGrid();
		
			#if defined (__IUL_LIAB_H_)
			if (hedge_group_bucket == 0) // setup second dimension to correct size based for buckets
				{
				hedge_group_bucket_size = sm_hedge_grp[hedge_group][hedge_group_bucket]->hedge_grp_crediting_mths;
				sm_hedge_grp[hedge_group].resize(hedge_group_bucket_size);
				}
			#endif

			if (hedge_grp_liab_counter != 0)
				{
				hedge_grp_loop_counter = hedge_grp_loop_counter + 1;
				hedge_grp_loop.insert(hedge_grploop::value_type(hedge_grp_loop_counter, hedge_group));	
				}	
					
			if (hedge_grp_liab_counter == 0)// cohort map counter varies by cohort
				{
				xstring curr_hedge_grp = hedge_grps[hedge_group];
				xstring error_msg = "Hedge Group " + curr_hedge_grp + " does not contain any model points. Please check your hedge group definition table.";
				log_screen << error_msg << MSG_ERROR;
				}
			
			total_mp_hedged += hedge_grp_liab_counter;
			}
		}
	}	
else // must recreate maps each projection task loop since investment assets are removed
	{
	if (hedge_valn_shock_flag)
		{
		// Reset values in hedge groups to remove the unnecessary group created
		for (int hedge_group = 0; hedge_group < sm_hedge_grp.size(); hedge_group++)
			{
			for (int hedge_group_bucket = 0; hedge_group_bucket < sm_hedge_grp[hedge_group].size(); hedge_group_bucket++)
				sm_hedge_grp[hedge_group][hedge_group_bucket]->resetValues();
			}
		}

	for (int hedge_group = 0; hedge_group < sm_hedge_grp.size(); hedge_group++)
		{
		for (int hedge_group_bucket = 0; hedge_group_bucket < sm_hedge_grp[hedge_group].size(); hedge_group_bucket++)
			sm_hedge_grp[hedge_group][hedge_group_bucket]->initialize(0);
		}
	}				
#endif

return;
}



