//factory
SEG_COMP* SEG_COMP::makeThis(int isSubmodel, ModelClass* owner, SEG_COMP* peer, 
						int mainRebase, const xstring &name, SEG_COMP_persistent_object* arrayTemplate) {
	#ifdef MEMORYPROFILE
		MemoryProfile mp("SEG_COMP::MakeThis");
	#endif
#ifdef USEMEMCOUNT
	gMem.setNewKey("ctor SEG_COMP");
#endif
	SEG_COMP* newP = (SEG_COMP*)new SEG_COMP_UDF
   	  ("seg_comp", isSubmodel, owner, peer, mainRebase, name, arrayTemplate);

	if (!CP) // first time around, CP wil be zero, store top_model pointer
   	CP = newP;
#ifdef USEMEMCOUNT
 	gMem.clearKey();
#endif

	newP->justSetGroupSharePtr(&dummySharedAttributes);

	// Store unique names in newly created model, if modelarray
	if (arrayTemplate) {
   	newP->meta = arrayTemplate->meta;
		newP->ms_Total((ModelClass*)arrayTemplate); // share total with persistent object
		newP->groupExpr = arrayTemplate->groupExpr;
	}
	else 
		newP->ms_Total(new TotalObject); // make a new total

		setVisitorPointersAndMap(name, newP, 'N');

	// create submodels of this model here
	newP->sm_ann_pba.setPersistentObject(ANN_PBA_PBA_persistent_object::makeThis(1, newP, (ANN_PBA_PBA*)(peer?peer->sm_ann_pba.getPersistentObject():0), mainRebase, name + "|ann_pba", arrayTemplate?arrayTemplate->sm_ann_pba.getPersistentObject():0, false));

	newP->sm_sfas97rd.setPersistentObject(SFAS97RD_GAAP_persistent_object::makeThis(1, newP, (SFAS97RD_GAAP*)(peer?peer->sm_sfas97rd.getPersistentObject():0), mainRebase, name + "|sfas97rd", arrayTemplate?arrayTemplate->sm_sfas97rd.getPersistentObject():0, false));

	newP->sm_hedge_grp.setPersistentObject(HDG_GRP_COMP_persistent_object::makeThis(1, newP, (HDG_GRP_COMP*)(peer?peer->sm_hedge_grp.getPersistentObject():0), mainRebase, name + "|hedge_grp", arrayTemplate?arrayTemplate->sm_hedge_grp.getPersistentObject():0, false));


	// only do this for topmodel created
   if (!arrayTemplate && newP == CP) {
		IsMainRebaseForClonesVisitor().visitAll(CP);
		IsMainRebaseForSubModelsVisitor().visitAll(CP);
	}

	return newP;
}

//factory
SEG_COMP_persistent_object* SEG_COMP_persistent_object::makeThis(int isSubmodel, ModelClass* owner, SEG_COMP* peer, 
							int mainRebase, const xstring &name, SEG_COMP_persistent_object* arrayTemplate, bool fixedArray) {
	#ifdef MEMORYPROFILE
		MemoryProfile mp("SEG_COMP_persistent_object::MakeThis");
	#endif
#ifdef USEMEMCOUNT
	gMem.setNewKey("ctor SEG_COMP_persistent_object");
#endif
	SEG_COMP_persistent_object* newP = (SEG_COMP_persistent_object*)new SEG_COMP_persistent_object
   	  ("seg_comp", isSubmodel, owner, peer, mainRebase, name, arrayTemplate);
#ifdef USEMEMCOUNT
 	gMem.clearKey();
#endif

	newP->justSetGroupSharePtr(&dummySharedAttributes);

	// Store unique names in newly created model, if modelarray

	if (!productWithSearchArray.empty() && arrayTemplate &&  arrayTemplate->isArrayModel())
	{
		for (auto &product : productWithSearchArray)
		{
			SEG_COMP_persistent_object* pd = dynamic_cast<SEG_COMP_persistent_object*>(product);
			if (pd)
			{
				newP->SearchFields = product->SearchFields;
			}
		}
	}

	if (arrayTemplate) {
   	newP->meta = arrayTemplate->meta;
		newP->ms_Total((ModelClass*)arrayTemplate); // share total with persistent object
		newP->groupExpr = arrayTemplate->groupExpr;
	}
	else 
		newP->ms_Total(new TotalObject); // make a new total

	if (!fixedArray)
		setVisitorPointersAndMap(name, newP, 'N');

	// create submodels of this model here
	newP->sm_ann_pba.setPersistentObject(ANN_PBA_PBA_persistent_object::makeThis(1, newP, (ANN_PBA_PBA*)(peer?peer->sm_ann_pba.getPersistentObject():0), mainRebase, name + "|ann_pba", arrayTemplate?arrayTemplate->sm_ann_pba.getPersistentObject():0, false));

	newP->sm_sfas97rd.setPersistentObject(SFAS97RD_GAAP_persistent_object::makeThis(1, newP, (SFAS97RD_GAAP*)(peer?peer->sm_sfas97rd.getPersistentObject():0), mainRebase, name + "|sfas97rd", arrayTemplate?arrayTemplate->sm_sfas97rd.getPersistentObject():0, false));

	newP->sm_hedge_grp.setPersistentObject(HDG_GRP_COMP_persistent_object::makeThis(1, newP, (HDG_GRP_COMP*)(peer?peer->sm_hedge_grp.getPersistentObject():0), mainRebase, name + "|hedge_grp", arrayTemplate?arrayTemplate->sm_hedge_grp.getPersistentObject():0, false));

	// only do this for topmodel created
   if (!arrayTemplate && newP == CP) {
		IsMainRebaseForClonesVisitor().visitAll(CP);
		IsMainRebaseForSubModelsVisitor().visitAll(CP);
	}

	newP->msnumelement.setValue(0);
	return newP;
}

